// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address from,
        address caddress,
        address[] memory _tos,
        uint v
    ) public {
        // Ensure at least 2 elements to call twice meaningfully
        if (_tos.length < 2) vm.assume(false);

        // Make first call
        (bool firstRevert, bytes memory firstRet) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v)
        );

        // Make second call with same parameters
        (bool secondRevert, bytes memory secondRet) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v)
        );

        // Both calls must have same revert status and same return value
        bool property = firstRevert == secondRevert && 
                        keccak256(firstRet) == keccak256(secondRet);

        assertTrue(property);
    }
}

