// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));

        // Deploy a simple contract that will return success/failure based on input
        uint successCount = 0;
        for(uint i = 0; i < _tos.length; i++) {
            (bool lastSuccess, ) = caddress.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[i], v));
            if(i == _tos.length - 1) {
                // After calling transfer, check if it returns the same as the last call
                (bool transferSuccess,) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
                if(transferSuccess) {
                    assertTrue(lastSuccess == true, "Return value mismatch");
                }
            }
        }
    }
}
